select jsonb_build_object('key','columns','rows',coalesce(jsonb_agg(row_data),'[]'::jsonb))::text from (select n.nspname as schema,c.relname as object,a.attnum as ordinal,a.attname as column,format_type(a.atttypid,a.atttypmod) as type,a.attnotnull as nn,a.attidentity::text as identity, a.attgenerated::text as generated,pg_get_expr(d.adbin,d.adrelid) as default from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname in ('public','loopa_private') and c.relkind='r' order by 1,2,3) row_data;
select jsonb_build_object('key','constraints','rows',coalesce(jsonb_agg(row_data),'[]'::jsonb))::text from (select n.nspname as schema,c.relname as object,x.conname as name,x.contype::text as kind,pg_get_constraintdef(x.oid) as ddl from pg_constraint x join pg_class c on c.oid=x.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','loopa_private') and c.relkind='r' order by 1,2,3) row_data;
select jsonb_build_object('key','indexes','rows',coalesce(jsonb_agg(row_data),'[]'::jsonb))::text from (select n.nspname as schema,c.relname as object,i.relname as name, pg_get_indexdef(i.oid) as ddl from pg_index x join pg_class c on c.oid=x.indrelid join pg_class i on i.oid=x.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','loopa_private') and c.relkind='r' and not exists(select 1 from pg_constraint q where q.conindid=i.oid and q.contype in ('p','u','x')) order by 1,2,3) row_data;
select jsonb_build_object('key','policies','rows',coalesce(jsonb_agg(row_data),'[]'::jsonb))::text from (select schemaname,tablename,policyname,permissive,roles::text,cmd,qual,with_check from pg_policies where schemaname in ('public','loopa_private') or (schemaname='storage' and (qual like '%avatars%' or with_check like '%avatars%')) order by 1,2,3) row_data;
select jsonb_build_object('key','tableacl','rows',coalesce(jsonb_agg(row_data),'[]'::jsonb))::text from (select n.nspname as schema,c.relname as object,c.relkind::text as kind,coalesce(r.rolname,'PUBLIC') as role,x.privilege_type as priv,x.is_grantable as grantable from pg_class c join pg_namespace n on n.oid=c.relnamespace cross join lateral aclexplode(coalesce(c.relacl,acldefault(case when c.relkind='S' then 'S'::"char" else 'r'::"char" end,c.relowner))) x left join pg_roles r on r.oid=x.grantee where n.nspname in ('public','loopa_private') and c.relkind in ('r','S') and x.grantee<>c.relowner order by 1,2,4,5) row_data;
select jsonb_build_object('key','colacl','rows',coalesce(jsonb_agg(row_data),'[]'::jsonb))::text from (select n.nspname as schema,c.relname as object,a.attname as column,coalesce(r.rolname,'PUBLIC') as role,x.privilege_type as priv,x.is_grantable as grantable from pg_class c join pg_namespace n on n.oid=c.relnamespace join pg_attribute a on a.attrelid=c.oid and a.attnum>0 and not a.attisdropped cross join lateral aclexplode(a.attacl) x left join pg_roles r on r.oid=x.grantee where n.nspname in ('public','loopa_private') and c.relkind='r' and x.grantee<>c.relowner order by 1,2,3,4,5) row_data;
select jsonb_build_object('key','proc_acl','rows',coalesce(jsonb_agg(row_data),'[]'::jsonb))::text from (select n.nspname as schema,p.proname as object,oidvectortypes(p.proargtypes) as args,coalesce(r.rolname,'PUBLIC') as role,x.privilege_type as priv,x.is_grantable as grantable from pg_proc p join pg_namespace n on n.oid=p.pronamespace cross join lateral aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) x left join pg_roles r on r.oid=x.grantee where n.nspname in ('public','loopa_private') and p.prokind='f' and x.grantee<>p.proowner order by 1,2,3,4,5) row_data;
select jsonb_build_object('key','proc_idx','rows',coalesce(jsonb_agg(row_data),'[]'::jsonb))::text from (select p.oid,n.nspname as schema,p.proname as name,oidvectortypes(p.proargtypes) as args,md5(translate(pg_get_functiondef(p.oid),chr(13),'')) as md5, length(pg_get_functiondef(p.oid)) as nbytes from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','loopa_private') and p.prokind='f' order by 2,3,4) row_data;
select jsonb_build_object('key','triggers','rows',coalesce(jsonb_agg(row_data),'[]'::jsonb))::text from (select n.nspname as schema,c.relname as object,t.tgname as name,t.tgenabled::text as enabled,pg_get_triggerdef(t.oid) as ddl from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and (n.nspname in ('public','loopa_private') or (n.nspname='auth' and t.tgfoid in (select oid from pg_proc where pronamespace in ('public'::regnamespace,'loopa_private'::regnamespace)))) order by 1,2,3) row_data;
select jsonb_build_object('key','events','rows',coalesce(jsonb_agg(row_data),'[]'::jsonb))::text from (select e.evtname as name,e.evtevent as event,e.evtenabled::text as enabled,e.evttags::text as tags,n.nspname as schema,p.proname as proc from pg_event_trigger e join pg_proc p on p.oid=e.evtfoid join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','loopa_private') order by 1) row_data;
select jsonb_build_object('key','schemaacl','rows',coalesce(jsonb_agg(row_data),'[]'::jsonb))::text from (select n.nspname as schema,coalesce(r.rolname,'PUBLIC') as role,x.privilege_type as priv,x.is_grantable as grantable from pg_namespace n cross join lateral aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) x left join pg_roles r on r.oid=x.grantee where n.nspname in ('public','loopa_private') and x.grantee<>n.nspowner order by 1,2,3) row_data;
select jsonb_build_object('key','sequence','rows',coalesce(jsonb_agg(row_data),'[]'::jsonb))::text from (select schemaname,sequencename,data_type::text,start_value,min_value,max_value::text,increment_by,cycle,cache_size from pg_sequences where schemaname in ('public','loopa_private') order by 1,2) row_data;
select jsonb_build_object('key','table_flags','rows',coalesce(jsonb_agg(r),'[]'::jsonb))::text from (select n.nspname as schema,c.relname as name,pg_get_userbyid(c.relowner) as owner,c.relkind::text as kind,c.relrowsecurity as rls,c.relforcerowsecurity as force_rls from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','loopa_private') and c.relkind in ('r','p','v','m','S') order by 1,2) r;
select jsonb_build_object('key','publication','rows',coalesce(jsonb_agg(r),'[]'::jsonb))::text from (select pubname,schemaname,tablename,attnames::text,rowfilter from pg_publication_tables where schemaname in ('public','loopa_private') order by 1,2,3) r;
select jsonb_build_object('key','avatar_bucket','rows',coalesce(jsonb_agg(r),'[]'::jsonb))::text from (select id,public,file_size_limit,allowed_mime_types::text from storage.buckets where id='avatars') r;
